referenceSolutionTemplate:
#include <stdio.h>

/* 限额：一碗最多报这么多条；这一排的碗数。
   一出生就不许再变的数，全大写。 */
#define FISH_LIMIT {lim}
#define BOWL_COUNT 3

/* 印一碗的账：第 N 碗几条；严格超过限额的在行尾缀「 超限！」。 */
void print_bowl(int index, int fish, int limit) {
    printf("第 %d 碗：%d 条", index, fish);
    if (fish > limit) {
        printf(" 超限！");
    }
    printf("\n");
}

int main(void) {
    int fish[3] = { {a}, {b}, {c} };
    for (int i = 0; i < BOWL_COUNT; i++) {
        print_bowl(i + 1, fish[i], FISH_LIMIT);
    }
    printf("合计 %d 条喵\n", fish[0] + fish[1] + fish[2]);
    return 0;
}
